public boolean shouldPrintMessage(int timestamp, String message) {
    // Cache of last printed timestamp per message
    // Use a static map to persist state across calls
    // (Assuming this method is part of a class where LOG is available)
    if (!_logFilterMap.containsKey(message)) {
        // message never printed before
        _logFilterMap.put(message, timestamp);
        return true;
