public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Serialize the message into the buffer
    buffer.clear();
    schema.writeTo(buffer, message);
    int size = buffer.size();
    // Encode the length as a varint and write it to out
    int v = size;
    while ((v & ~0x7F) != 0) {
        out.write((v & 0x7F) | 0x80);
        v >>>= 7;
    }
    out.write(v);
    // Flush the serialized message to out
    buffer.writeTo(out);
    return size;
}<|return|>

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    int rawSize = schema.getSerializedSize(message, buffer);
    int sizeToWrite = rawSize;
    while (true) {
        if ((sizeToWrite & ~0x7F) == 0) {
            out.write(sizeToWrite);
            break;
        } else {
            out.write((sizeToWrite & 0x7F) | 0x80);
            sizeToWrite >>>= 7;
        }
    }
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    schema.writeTo(message, cos);
    cos.flush();
    return rawSize;
