    if (start > end) {
        return ranges;
    }
    long current = start;
    while (current <= end) {
        long endRange = Math.min(current + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(current, endRange));
        if (endRange == end) {
            break;
        }
        current = endRange + 1;
    }
    return ranges;
