public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int end = index + len;
    if (end > str.length() || index < 0 || len < 0) {
        throw new IndexOutOfBoundsException("index=" + index + ", len=" + len + ", str.length()=" + str.length());
    }
    int i = index;
    int utf8Size = 0;
    while (i < end) {
        int cp = str.codePointAt(i);
        if (cp <= 0x7F) {
            utf8Size += 1;
        } else if (cp <= 0x7FF) {
            utf8Size += 2;
        } else if (cp <= 0xFFFF) {
            utf8Size += 3;
        } else {
            utf8Size += 4;
        }
        i += Character.charCount(cp);
    }
    return utf8Size;
