        pos = 1;
        while (descriptor.charAt(pos) != ')') {
            // Skip array brackets
            while (descriptor.charAt(pos) == '[') {
                pos++;
            }
            char c = descriptor.charAt(pos);
            if (c == 'L') {
                // Object type: consume until ';'
                pos = descriptor.indexOf(';', pos);
