protected int removeUnusedNodes(){
    int count = 0;
    // Assume 'root' is the root node of the Category tree
    if (root == null) {
        return 0;
    }
    Deque<Category> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category node = stack.pop();
        List<Category> children = node.getChildren();
        if (children != null) {
            // Iterate backwards to safely remove elements
            for (int i = children.size() - 1; i >= 0; i--) {
                Category child = children.get(i);
                if (!child.isActive()) {
                    children.remove(i);
                    count++;
                } else {
                    stack.push(child);
                }
            }
        }
    }
    return count;
