private void moveAllListNodes(DoublyLinkedList<E> list) {
    // If the source list is empty or the same as this list, nothing to do.
    if (list == this || list.head == null) {
        return;
    }

    // Keep a reference to the size of the source list.
    int movedSize = list.size;

    // Splice the source list into this list.
    if (this.head == null) {
        // This list is empty – just adopt the source's head and tail.
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Link this list's tail to the source's head.
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }

    // Update the size.
    this.size += movedSize;

    // Clear the source list.
    list.head = null;
    list.tail = null;
    list.size = 0;
