public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    while (true) {
        int b = input_.read();
        if (b == -1) {
            return 0;
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return tag;
        }
        shift += 7;
    }
}<|return|>

